// --- 2. OBTENER DATOS DE LA IA Y NODOS PREVIOS ---
let llmOutput = {};
let error_type = $input.first().json.error?.type || null;

try {
  llmOutput = JSON.parse($input.first().json.output.replace(/```json/gi, '').replace(/```/g, '').trim());
} catch (e) {
  llmOutput = { intent: "uncertain", confidence: 0, reason: "Error de parseo" };
}
if (!llmOutput.extracted) llmOutput.extracted = {};

let session_id = "";
let conversation_id = "";
let message_id = "";
let message_text = "";
let display_name = "";
let timestamp = new Date().toISOString();
let session_memory = {};
let soft_customer_context = {};

try {
  // Leemos los datos directamente de M1
  const m1Data = $('When Executed by Another Workflow').first().json;
  session_id = m1Data.session?.session_id || m1Data.user?.user_id || "";
  conversation_id = m1Data.session?.conversation_id || "";
  display_name = m1Data.user?.display_name || "";
  message_id = m1Data.message?.message_id || "";
  message_text = m1Data.message?.text || $input.first().json.input?.text || "";
  timestamp = m1Data.message?.timestamp || timestamp;
  // Obtenemos la memoria del nodo que la adjuntó
  session_memory = $('Attach Session Memory To Turn').first().json.session_memory || {};
  soft_customer_context = $('Attach Session Memory To Turn').first().json.soft_customer_context || {
    has_relevant_memory: false,
    memory_confidence: 'none',
    safe_summary: null,
    conversation_cues: [],
    do_not_say: []
  };
} catch(e) { }

// --- 3. REGLAS BASE DE RUTEO ---
let destination = "fallback";
let stage = "unknown";
let needs_memory = false;

switch(llmOutput.intent) {
  case 'general_inquiry':
    destination = "m3_advisor"; stage = "exploration"; break;
  case 'product_search':
    destination = "m3_advisor"; stage = "consideration"; break;
  case 'product_specific':
    destination = "m3_advisor"; stage = "consideration";
    if (!llmOutput.extracted?.product_candidate) needs_memory = true;
    break;
  case 'purchase_intent':
    destination = "m5_commerce_lite"; stage = "intent";
    if (!llmOutput.extracted?.product_candidate) needs_memory = true;
    break;
  case 'human_request':
    // El handoff se manejará en detalle en el paso 5
    destination = "m6_handoff"; stage = "handoff"; break; 
  case 'uncertain':
  case 'unsupported':
  default:
    destination = "fallback"; stage = "unknown"; break;
}

// --- 4. APLICAR REGLAS DE MEMORIA ---
const referencedProduct = resolveReferencedProduct(message_text, session_memory);

if (session_memory.usable && referencedProduct) {
  if (hasContextualPurchaseSignal(message_text)) {
    llmOutput.intent = 'purchase_intent';
    destination = 'm5_commerce_lite';
    stage = 'intent';
    llmOutput.reason = 'Referencia contextual resuelta desde memoria con señal de compra.';
  } else if (hasContextualPriceSignal(message_text)) {
    llmOutput.intent = 'product_specific';
    destination = 'm3_advisor';
    stage = 'consideration';
    llmOutput.reason = 'Referencia contextual resuelta desde memoria con consulta de precio o detalle.';
  } else {
    llmOutput.intent = 'product_specific';
    destination = 'm3_advisor';
    stage = 'consideration';
    llmOutput.reason = 'Referencia contextual resuelta desde memoria de sesión.';
  }

  llmOutput.extracted.product_candidate = referencedProduct.display_name || '';
  llmOutput.extracted.category_candidate = referencedProduct.category || llmOutput.extracted.category_candidate || null;
  llmOutput.extracted.preference = llmOutput.extracted.preference || session_memory.commercial_context?.last_preference_detected || null;

  llmOutput.extracted.memory_resolved = true;
  llmOutput.extracted.memory_resolution = {
    resolved_from_memory: true,
    resolved_product: referencedProduct.display_name || '',
    resolved_category: referencedProduct.category || '',
    resolution_source: 'session_memory'
  };

  needs_memory = false;
}

// --- 5. NORMALIZACIÓN Y REGLAS DE HANDOFF ---
let handoffRequired = false;
let handoffReason = null;
let handoffPriority = 'low';
let handoffTriggeredBy = null;
const confidenceScore = Number(llmOutput.confidence ?? 0);

// a) Verificación por intención del LLM
if (llmOutput.intent === 'human_request') {
  handoffRequired = true;
  handoffReason = 'human_request';
  handoffPriority = 'medium';
  handoffTriggeredBy = 'llm_intent';
}

// b) Verificación por señales explícitas en el texto del usuario
if (!handoffRequired && includesAny(message_text, explicitHumanSignals)) {
  handoffRequired = true;
  handoffReason = 'human_request';
  handoffPriority = 'medium';
  handoffTriggeredBy = 'explicit_user_request';
}

// c) Verificación por baja confianza o intención incierta
if (!handoffRequired && (llmOutput.intent === 'uncertain' || llmOutput.intent === 'unknown' || confidenceScore < 0.55)) {
  handoffRequired = true;
  handoffReason = 'low_confidence';
  handoffPriority = 'medium';
  handoffTriggeredBy = 'low_confidence_or_unknown_intent';
}

// d) Verificación por errores técnicos
if (!handoffRequired && technicalSignals.includes(clean(error_type))) {
  handoffRequired = true;
  handoffReason = 'technical_error';
  handoffPriority = 'high';
  handoffTriggeredBy = 'technical_error';
}

// Sobrescribir ruteo si se exige Handoff
if (handoffRequired) {
  destination = "m6_handoff";
  stage = "handoff";
  // Limpiamos la intención a "unknown" si el handoff no fue por petición directa
  if (llmOutput.intent !== 'human_request' && handoffReason !== 'human_request') {
    llmOutput.intent = llmOutput.intent || 'unknown';
  }
}

// --- 6. CONSTRUCCIÓN DEL CONTRATO FINAL GIGANTE ---
const finalContract = {
  "schema_version": "dalia.m2.routing_decision.v1",
  "trace": {
    "event_id": "evt_" + Date.now(),
    "conversation_id": conversation_id,
    "session_id": session_id
  },
  "context": {
    "environment": "demo",
    "business_id": "business_demo",
    "channel": "whatsapp",
    "user_id": session_id, // Tomado de la resolución segura anterior
    "display_name": display_name
  },
  "input": {
    "message_id": message_id,
    "type": "text",
    "text": message_text,
    "timestamp": timestamp,
    "processing_status": "ready"
  },
  "decision": {
    "intent": llmOutput.intent || "uncertain",
    "destination": destination,
    "confidence": llmOutput.confidence || confidenceScore || 0.9,
    "commercial_stage": stage,
    "reason": llmOutput.reason || "",
    "handoff": {
      "required": handoffRequired,
      "reason": handoffReason,
      "priority": handoffPriority,
      "triggered_by": handoffTriggeredBy
    }
  },
  "extracted": llmOutput.extracted || {
    "category_candidate": null,
    "product_candidate": null,
    "quantity": null,
    "city": null,
    "preference": null
  },
  "control": {
    "needs_clarification": (destination === "fallback"),
    "needs_memory_lookup": needs_memory,
    "requires_handoff": handoffRequired,
    "fallback_reason": (destination === "fallback") ? "ambiguous_message" : null
  },
  "session_memory": session_memory,
  "soft_customer_context": soft_customer_context
};

return { json: finalContract };

